VALUES('re-target-system:growin-architecture:1.0-bc:growin-application:growin', 0, 'maro2', 1790131488937, 'maro2', 1790131488937, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', 'growin', 'Create a reviewable Rega draft for the Growin bounded context, covering the Growin Application, ten actor-and-situation-based MicroApps, one cohesive Growin MicroService, role mappings, provider capabilities, and use-case capability needs.', 'Growin', 're-target-system:growin-architecture:1.0-bc:growin');
VALUES('re-target-system:growin-architecture:1.0-bc:growin-application:growin-spec', 1, 'maro', 1790142225346, 'maro2', 1790131488945, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"businessPurpose":"Reduce academy recruitment burden, help interested learners voluntarily select an academy, and preserve evidence for recruitment outcomes and costs.","userValue":"Learners can engage voluntarily and choose an academy with explicit consent, while operators and academies can manage recruitment and review evidence-backed outcomes.","expectedOutcome":"A reviewable Growin business specification covering the complete recruitment-growth journey through ten usage contexts and one cohesive business service.","ownerOrganization":null,"targetOrganizations":null,"scope":{"inScopes":["Recruitment networks, participating academies, eligible offers, and trial schedules","Demand evidence, reviewed content, campaigns, and acquisition tracking","Voluntary learning, preferences, contact verification, and purpose-specific consent","Academy selection, consultation transfer, trial booking, and follow-up","Outcome projections, attribution, performance analysis, costs, settlements, and referral rewards"],"outOfScopes":["Canonical student, enrollment, course, and attendance ledgers","Canonical Lead and consultation ledger","Canonical payment and refund transactions, tax-invoice issuance, remittance, and reward payout execution","Free-form web-page building and P0 automatic pronunciation assessment","Collection of personal prospect lists without consent","Identity, authorization, secret storage, file storage, generation-provider, and notification-delivery platform responsibilities"]},"stakeholders":[{"key":"marketing-manager","name":"Marketing Manager","role":"marketing-manager","goals":["Operate recruitment networks, demand evidence, campaigns, follow-up, reporting, and separately authorized commercial work."],"protectedInterests":["Commercial authority must not be implied by general marketing access."]},{"key":"contents-manager","name":"Contents Manager","role":"contents-manager","goals":["Plan, produce, localize, and review versioned recruitment and learning content."],"protectedInterests":["Unmasked consultation contacts must remain outside content-production access."]},{"key":"academy-manager","name":"Academy Manager","role":"academy-manager","goals":["Manage the academy''s recruitment, trials, consultation work, performance, and settlement review within its academy boundary."],"protectedInterests":["Other academies'' data and unauthorized financial authority must remain inaccessible."]},{"key":"rookie","name":"Rookie","role":"rookie","goals":["Learn voluntarily, control preferences and consent, choose an academy, and request consultation or trials."],"protectedInterests":["Participation must not create an unsolicited consultation transfer or reveal another participant''s identity."]}],"journey":{"startStepKey":"recruitment-preparation","steps":[{"key":"recruitment-preparation","microAppCode":"recruitmentpreparation"},{"key":"demand-discovery","microAppCode":"demanddiscovery"},{"key":"content-production","microAppCode":"contentstudio"},{"key":"campaign-publishing","microAppCode":"campaigns"},{"key":"learning-engagement","microAppCode":"learning"},{"key":"academy-connection","microAppCode":"academyconnection"},{"key":"consultation-followup","microAppCode":"consultation"},{"key":"performance-analysis","microAppCode":"performance"},{"key":"cost-settlement","microAppCode":"settlement"},{"key":"referral-rewards","microAppCode":"referrals"}],"transitions":[{"key":"preparation-to-demand","fromStepKey":"recruitment-preparation","toStepKey":"demand-discovery","flowType":"NORMAL","condition":"Recruitment supply is available and demand planning begins."},{"key":"demand-to-content","fromStepKey":"demand-discovery","toStepKey":"content-production","flowType":"NORMAL","condition":"An evidence-backed content need is accepted."},{"key":"content-to-campaign","fromStepKey":"content-production","toStepKey":"campaign-publishing","flowType":"NORMAL","condition":"A fixed content revision has the required reviews and rights evidence."},{"key":"campaign-to-learning","fromStepKey":"campaign-publishing","toStepKey":"learning-engagement","flowType":"NORMAL","condition":"A visitor arrives through published content or a participation page."},{"key":"learning-to-connection","fromStepKey":"learning-engagement","toStepKey":"academy-connection","flowType":"NORMAL","condition":"A participant elects to compare offers, request contact, book a trial, or wait."},{"key":"connection-to-followup","fromStepKey":"academy-connection","toStepKey":"consultation-followup","flowType":"NORMAL","condition":"An authorized consultation transfer or confirmed trial requires academy follow-up."},{"key":"followup-to-performance","fromStepKey":"consultation-followup","toStepKey":"performance-analysis","flowType":"NORMAL","condition":"Canonical enrollment, payment, refund, or attendance evidence is available."},{"key":"performance-to-settlement","fromStepKey":"performance-analysis","toStepKey":"cost-settlement","flowType":"NORMAL","condition":"Verified evidence and an approved policy support charge review."},{"key":"learning-to-referrals","fromStepKey":"learning-engagement","toStepKey":"referral-rewards","flowType":"OPTIONAL","condition":"A P1 referral program and participant agreement are active."}],"endConditions":["Recruitment results and commercial evidence are reviewable without duplicate source facts or charges.","Any activated referral reward is evidence-backed and privacy-limited."]},"commonContexts":[{"key":"network-context","name":"Network Context","description":"The recruitment network, region, language, locale, time zone, currency, and access boundary relevant to an interaction.","source":"KX-GROWIN, L01, and SUP01"},{"key":"academy-context","name":"Academy Context","description":"The selected or authorized academy boundary used for offers, transfers, consultation, reporting, and settlement.","source":"R03, R05, SUP01, and T04"},{"key":"participant-consent-context","name":"Participant Consent Context","description":"The participant, verified contact state, purpose, recipient academy, channel, and current consent decision.","source":"R02-R04 and SUP02"},{"key":"source-evidence-context","name":"Source Evidence Context","description":"Canonical source identifiers, evidence timestamps, source ownership, and reconciliation status used without replacing source ledgers.","source":"R01, R12, and SUP05"}],"policies":[{"key":"explicit-academy-choice","category":"Consent","name":"Explicit academy choice","statement":"Growin must transfer participant information only to an explicitly selected academy under current recipient-specific consent."},{"key":"source-ledger-ownership","category":"Ownership","name":"Source ledger ownership","statement":"Growin must preserve source references and projections without replacing canonical Lead, enrollment, attendance, payment, or refund ledgers."},{"key":"phase-controlled-activation","category":"Release","name":"Phase-controlled activation","statement":"P1 and P2 automation must remain inactive until applicable permissions, provider contracts, review controls, and operating policies are approved."}],"qualityRequirements":[{"key":"tenant-isolation","category":"Security","expectation":"Network, academy, participant, export, and asynchronous-work access is checked server-side.","measure":"Cross-academy and cross-network direct access, search, and export attempts reveal no protected data."},{"key":"financial-integrity","category":"Integrity","expectation":"Confirmed financial records remain immutable and duplicate source transactions, charges, and adjustments are prevented.","measure":"Acceptance scenarios T13-T17 pass without duplicate effects."},{"key":"accessible-localized-use","category":"Usability","expectation":"Primary public actions remain usable in localized mobile and keyboard interaction.","measure":"Acceptance scenarios T19-T20 pass for the approved launch locales and devices."}],"supplementarySpec":null,"acceptanceCriteria":[{"key":"no-overbooking","statement":"Concurrent trial requests never confirm more seats than the trial capacity."},{"key":"no-cross-academy-leakage","statement":"An academy cannot view, search, or export another academy''s protected participant or consultation data."},{"key":"no-unconsented-transfer","statement":"Anonymous learning or marketing consent alone never creates an academy consultation transfer."},{"key":"no-duplicate-source-effect","statement":"Reprocessing source enrollment, payment, refund, or transfer evidence does not duplicate business outcomes or charges."}],"openIssues":[{"key":"application-owner-organization","question":"Which organization owns the Growin Application specification?","decision":null,"resolved":false,"blocking":false},{"key":"initial-operating-scope","question":"Which academies, channels, locales, currencies, and responsible operators are approved for the initial pilot?","decision":null,"resolved":false,"blocking":false},{"key":"operating-policy-values","question":"Which retention periods, message limits, quiet hours, retry limits, escalation thresholds, recovery objectives, and backup schedules are approved?","decision":null,"resolved":false,"blocking":false}]}', 're-target-system:growin-architecture:1.0-bc:growin-application:growin', 'Approved', '0.1.0');

