VALUES('re-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:contentstudio-episode-spec', 1, 'maro', 1790142148872, 'maro2', 1790131488991, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"oneLineDefinition":"Produce localized, rights-supported content with one valid next action and two qualified reviews.","businessPurpose":"Produce a localized, rights-supported content revision with one valid next action and both required reviews before publication.","responsibleOrganization":null,"situationContext":{"startBusinessEvent":"An accepted brief or approved content need is ready for production.","businessSubject":"Fixed content revision","endConditions":["The fixed revision has rights evidence, one valid next action, and both qualified approvals."]},"stakeholders":[{"key":"contents-manager","name":"contents-manager","role":"Contents Manager","goals":["Plan, produce, localize, and review publication-ready content."],"protectedInterests":["Unmasked consultation contacts remain inaccessible."]}],"acts":[{"key":"contents-manager","name":"contents-manager","stakeholderKey":"contents-manager","responsibility":"Plan, produce, localize, and coordinate qualified review of content."}],"useCases":[{"key":"content-series-planning","name":"Content series planning","actKey":"contents-manager","userGoal":"Define the content purpose, audience, owner, schedule, and next action.","trigger":"An accepted brief or approved content need exists.","endConditions":["A traceable content series and production responsibility are defined."],"capabilityNeeds":[{"key":"series-plan-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"plan-content-series","businessPurpose":"Define the content series and next action.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"content-revision-production","name":"Content revision production","actKey":"contents-manager","userGoal":"Create a versioned script and media package with preserved generation and rights evidence.","trigger":"A content item is assigned for production.","endConditions":["A versioned revision preserves assets, generation attempts, costs, and rights evidence."],"capabilityNeeds":[{"key":"revision-production-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"produce-content-revision","businessPurpose":"Produce a versioned content revision.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"content-localization","name":"Content localization","actKey":"contents-manager","userGoal":"Prepare language and channel variants for review.","trigger":"A source revision and target language or format are selected.","endConditions":["Comparable localized variants remain linked to the source revision."],"capabilityNeeds":[{"key":"localization-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"localize-content-revision","businessPurpose":"Prepare reviewable localized variants.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"content-action-design","name":"Content action design","actKey":"contents-manager","userGoal":"Connect the revision to one available primary next action.","trigger":"A localized revision needs its destination.","endConditions":["Exactly one valid primary action or approved fallback is fixed."],"capabilityNeeds":[{"key":"content-action-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"set-content-call-to-action","businessPurpose":"Fix one valid next action on the revision.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"content-quality-approval","name":"Content quality approval","actKey":"contents-manager","userGoal":"Obtain independent Korean-learning and local-language decisions on the same fixed revision.","trigger":"The revision, assets, rights evidence, and next action are fixed.","endConditions":["Both qualified decisions apply to the same revision or rework is requested."],"capabilityNeeds":[{"key":"korean-review-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"review-korean-learning-quality","businessPurpose":"Obtain Korean-learning quality review.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"local-review-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"review-local-language-suitability","businessPurpose":"Obtain independent local-language suitability review.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]}],"useCaseFlows":[{"key":"plan-to-production","fromUseCaseKey":"content-series-planning","toUseCaseKey":"content-revision-production","flowType":"NORMAL","condition":"A content item is assigned for production."},{"key":"production-to-localization","fromUseCaseKey":"content-revision-production","toUseCaseKey":"content-localization","flowType":"NORMAL","condition":"A source revision is available for the target language and format."},{"key":"localization-to-action","fromUseCaseKey":"content-localization","toUseCaseKey":"content-action-design","flowType":"NORMAL","condition":"The localized revision requires its publication action and destination."},{"key":"action-to-review","fromUseCaseKey":"content-action-design","toUseCaseKey":"content-quality-approval","flowType":"NORMAL","condition":"The revision, assets, rights evidence, and primary action are fixed for review."},{"key":"review-to-revision","fromUseCaseKey":"content-quality-approval","toUseCaseKey":"content-revision-production","flowType":"REWORK","condition":"Either qualified reviewer requests changes."}],"dramaParticipations":[{"key":"content-production-participation","microserviceCode":"growin","stakeholderKey":"contents-manager","dramaRoleKey":"content-producer","accessPurpose":"Plan, produce, localize, and prepare fixed content revisions.","accessConditions":["Unmasked consultation contacts are inaccessible."]},{"key":"content-review-participation","microserviceCode":"growin","stakeholderKey":"contents-manager","dramaRoleKey":"content-reviewer","accessPurpose":"Perform qualified review of fixed revisions.","accessConditions":["The applicable Korean-learning or local-language qualification must be assigned.","Self-approval remains subject to the unresolved segregation-of-duties policy."]}],"contexts":[],"eventReactions":null,"policies":[{"key":"fixed-revision-review","category":"Content","name":"Fixed-revision review","statement":"Both reviews must approve the same fixed revision; any later content change requires a new revision and renewed reviews."}],"acceptanceCriteria":[{"key":"dual-review-before-publication","statement":"Content cannot become publication-ready until both qualified reviews approve the same fixed revision."}],"openIssues":[],"summaryUseCases":null}', 're-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:contentstudio', 'Approved', '0.1.0');
VALUES('re-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:academyconnection-episode-spec', 1, 'maro', 1790142184431, 'maro2', 1790131488996, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"oneLineDefinition":"Help a participant compare eligible offers and explicitly choose consultation, a trial, or waiting.","businessPurpose":"Connect the participant only to an explicitly selected academy or record unmet demand without creating an unauthorized Lead.","responsibleOrganization":null,"situationContext":{"startBusinessEvent":"A participant wants to find an eligible course, request consultation or a trial, or wait for a future match.","businessSubject":"Academy choice and connection","endConditions":["An authorized academy transfer or valid trial is accepted, or unmet demand is recorded without a Lead."]},"stakeholders":[{"key":"rookie","name":"rookie","role":"Rookie","goals":["Compare eligible offers and explicitly choose consultation, a trial, or waiting."],"protectedInterests":["No academy receives data without explicit choice and recipient-specific consent."]},{"key":"marketing-manager","name":"marketing-manager","role":"Marketing Manager","goals":["Review unmet demand and notify currently consenting participants."],"protectedInterests":[]}],"acts":[{"key":"rookie","name":"rookie","stakeholderKey":"rookie","responsibility":"Choose among eligible offers, consultation, trials, and waiting."},{"key":"marketing-manager","name":"marketing-manager","stakeholderKey":"marketing-manager","responsibility":"Review unmatched demand and consented notification opportunities."}],"useCases":[{"key":"course-selection","name":"Course selection","actKey":"rookie","userGoal":"Compare eligible offers with transparent reasons and source-aware scope.","trigger":"The participant requests course discovery.","endConditions":["Eligible choices and reasons are presented without inferring unknown preferences."],"capabilityNeeds":[{"key":"course-comparison-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"compare-recruitment-offers","businessPurpose":"Present reproducible eligible offers.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"consultation-request","name":"Consultation request","actKey":"rookie","userGoal":"Request contact from one selected academy.","trigger":"The participant explicitly selects an academy and requests consultation.","endConditions":["One idempotent transfer is accepted with verified contact and recipient-specific consent."],"capabilityNeeds":[{"key":"consultation-transfer-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"request-academy-consultation","businessPurpose":"Create the selected academy transfer.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"unmet-demand-waiting","name":"Unmet demand waiting","actKey":"rookie","userGoal":"Join, update, or leave a waitlist without creating an academy Lead.","trigger":"No suitable offer exists or the participant elects to wait.","endConditions":["Current waiting preferences and notice consent are recorded separately from transfer."],"capabilityNeeds":[{"key":"waitlist-entry-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"manage-waitlist-entry","businessPurpose":"Manage unmet-demand waiting.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"trial-booking","name":"Trial booking","actKey":"rookie","userGoal":"Secure a valid trial seat and related transfer intent.","trigger":"The participant selects an available trial.","endConditions":["One capacity-valid booking and related transfer intent are confirmed."],"capabilityNeeds":[{"key":"trial-booking-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"book-trial","businessPurpose":"Confirm the trial within capacity and consent constraints.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"trial-booking-management","name":"Trial booking management","actKey":"rookie","userGoal":"Change or cancel an existing trial without losing capacity consistency.","trigger":"The participant requests a booking change or cancellation.","endConditions":["A failed change preserves the original; cancellation releases the seat exactly once."],"capabilityNeeds":[{"key":"trial-change-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"change-trial-booking","businessPurpose":"Move a booking atomically.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"trial-cancel-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"cancel-trial-booking","businessPurpose":"Cancel the booking and release capacity.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"waitlist-matching","name":"Waitlist matching","actKey":"marketing-manager","userGoal":"Find newly matching offers and notify participants with current consent.","trigger":"New offers or a waitlist review period becomes available.","endConditions":["Eligible notification opportunities are identified without creating academy transfers."],"capabilityNeeds":[{"key":"waitlist-review-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"review-waitlist-demand","businessPurpose":"Review matching demand under current notice consent.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]}],"useCaseFlows":[{"key":"selection-to-consultation","fromUseCaseKey":"course-selection","toUseCaseKey":"consultation-request","flowType":"NORMAL","condition":"The participant explicitly selects an academy and requests consultation."},{"key":"selection-to-trial","fromUseCaseKey":"course-selection","toUseCaseKey":"trial-booking","flowType":"ALTERNATIVE","condition":"The participant selects an available trial and satisfies contact and consent requirements."},{"key":"selection-to-waiting","fromUseCaseKey":"course-selection","toUseCaseKey":"unmet-demand-waiting","flowType":"ALTERNATIVE","condition":"No suitable offer exists and the participant elects to wait."}],"dramaParticipations":[{"key":"rookie-connection-participation","microserviceCode":"growin","stakeholderKey":"rookie","dramaRoleKey":"learning-participant","accessPurpose":"Compare offers and explicitly request an academy connection or trial.","accessConditions":["Recipient-specific consent and verified contact are required for transfer."]},{"key":"marketing-waitlist-participation","microserviceCode":"growin","stakeholderKey":"marketing-manager","dramaRoleKey":"marketing-operator","accessPurpose":"Review unmet demand and consented notification opportunities.","accessConditions":["A notice is not an academy transfer."]}],"contexts":[],"eventReactions":null,"policies":[{"key":"explicit-selection-before-transfer","category":"Consent","name":"Explicit selection before transfer","statement":"Recommendation scope never substitutes for explicit academy selection and recipient-specific transfer consent."},{"key":"trial-capacity-consistency","category":"Booking","name":"Trial capacity consistency","statement":"Only one request may receive the final seat, and a failed move preserves the original booking."}],"acceptanceCriteria":[{"key":"selected-academy-only","statement":"Consultation information is transferred only to the academy explicitly selected by the participant."},{"key":"no-waitlist-lead","statement":"Joining or receiving a waitlist notice does not create an academy Lead."}],"openIssues":[],"summaryUseCases":null}', 're-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:academyconnection', 'Approved', '0.1.0');
VALUES('re-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:campaigns-episode-spec', 1, 'maro', 1790142187932, 'maro2', 1790131488993, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"oneLineDefinition":"Publish approved content through authorized channels with traceable ownership, links, and spend.","businessPurpose":"Publish approved content while preserving campaign ownership, reliable acquisition links, actual publication evidence, and sourced expenditure.","responsibleOrganization":null,"situationContext":{"startBusinessEvent":"Approved content and an authorized channel are available for a recruitment campaign.","businessSubject":"Recruitment campaign","endConditions":["Publication, acquisition ownership, channel performance, and actual spend are traceable."]},"stakeholders":[{"key":"marketing-manager","name":"marketing-manager","role":"Marketing Manager","goals":["Prepare channels and operate traceable recruitment campaigns."],"protectedInterests":[]},{"key":"academy-manager","name":"academy-manager","role":"Academy Manager","goals":["Coordinate campaigns owned by the academy."],"protectedInterests":["Academy campaign scope remains limited to the authorized academy."]}],"acts":[{"key":"marketing-manager","name":"marketing-manager","stakeholderKey":"marketing-manager","responsibility":"Prepare channels and operate traceable campaigns."},{"key":"academy-manager","name":"academy-manager","stakeholderKey":"academy-manager","responsibility":"Coordinate academy-owned campaigns."}],"useCases":[{"key":"campaign-setup","name":"Campaign setup","actKey":"marketing-manager","userGoal":"Prepare an authorized channel and define a traceable campaign.","trigger":"Approved campaign intent and channel access are available.","endConditions":["Channel capabilities, ownership, period, audience, participants, and budget are recorded."],"capabilityNeeds":[{"key":"campaign-channel-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"prepare-channel","bu