":[{"key":"assigned-history-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"view-assigned-consultation-history","businessPurpose":"View the authorized consultation case.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"consultation-work-management","name":"Consultation work management","actKey":"academy-manager","userGoal":"Assign consultation work, meet a human-response target, and record outcomes.","trigger":"An authorized case requires assignment or follow-up.","endConditions":["Assignment, original deadline, human attempts, successful contact, and outcomes are recorded distinctly."],"capabilityNeeds":[{"key":"consultation-assignment-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"assign-consultation","businessPurpose":"Assign an authorized counselor and response deadline.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"consultation-outcome-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"record-consultation-outcome","businessPurpose":"Record distinct consultation facts and outcomes.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"trial-attendance-management","name":"Trial attendance management","actKey":"academy-manager","userGoal":"Record attendance or no-show for the final completed trial.","trigger":"The final trial has ended.","endConditions":["Attendance or no-show is recorded only against the final booking."],"capabilityNeeds":[{"key":"trial-attendance-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"record-trial-attendance","businessPurpose":"Record the final trial attendance outcome.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"response-alert-management","name":"Response alert management","actKey":"academy-manager","userGoal":"Resolve or escalate imminent and overdue consultation work.","trigger":"A response deadline is imminent or overdue.","endConditions":["Responsible action or escalation is recorded without counting automation as human response."],"capabilityNeeds":[{"key":"response-alert-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"handle-response-alert","businessPurpose":"Handle the response alert responsibly.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"authorized-history-review","name":"Authorized history review","actKey":"marketing-manager","userGoal":"Review participant and valid consultation-candidate history within authority.","trigger":"An authorized operational need requires review.","endConditions":["Participant and consultation-candidate histories remain distinct and properly masked."],"capabilityNeeds":[{"key":"participant-history-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"review-participant-history","businessPurpose":"Review permitted operational history.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"delayed-consultation-support","name":"Delayed consultation support","actKey":"marketing-manager","userGoal":"Support an overdue consultation within academy policy and participant consent.","trigger":"A consultation is delayed and central support may be permitted.","endConditions":["Support actions, responsibility, and approved non-overlapping time are recorded."],"capabilityNeeds":[{"key":"delayed-support-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"support-delayed-consultation","businessPurpose":"Record permitted central support.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"consented-followup","name":"Consented follow-up","actKey":"marketing-manager","userGoal":"Send P1 information to currently consenting recipients.","trigger":"An eligible P1 audience and purpose are selected.","endConditions":["Only currently consenting recipients receive frequency-limited information."],"capabilityNeeds":[{"key":"consented-message-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"send-consented-followup","businessPurpose":"Send purpose-specific P1 follow-up.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]}],"useCaseFlows":[{"key":"review-to-work","fromUseCaseKey":"consultation-case-review","toUseCaseKey":"consultation-work-management","flowType":"NORMAL","condition":"An authorized consultation case requires assignment or follow-up."},{"key":"work-to-alert","fromUseCaseKey":"consultation-work-management","toUseCaseKey":"response-alert-management","flowType":"ALTERNATIVE","condition":"The response deadline is imminent or overdue."},{"key":"alert-to-support","fromUseCaseKey":"response-alert-management","toUseCaseKey":"delayed-consultation-support","flowType":"ALTERNATIVE","condition":"Academy policy and participant consent permit central support."}],"dramaParticipations":[{"key":"academy-consultation-participation","microserviceCode":"growin","stakeholderKey":"academy-manager","dramaRoleKey":"academy-operator","accessPurpose":"Operate assigned academy consultation and trial work.","accessConditions":["Limited to the authorized academy and assignment scope."]},{"key":"marketing-consultation-participation","microserviceCode":"growin","stakeholderKey":"marketing-manager","dramaRoleKey":"marketing-operator","accessPurpose":"Review permitted histories and provide consented central support.","accessConditions":["Academy policy, participant consent, masking, and network scope apply."]}],"contexts":[],"eventReactions":null,"policies":[{"key":"attempt-contact-separation","category":"Consultation","name":"Attempt and contact separation","statement":"A human attempt used for response timing remains distinct from successful contact, and automated acknowledgement counts as neither."}],"acceptanceCriteria":[{"key":"academy-history-isolated","statement":"Academy users can view only authorized transferred summaries and their own consultation and trial history."},{"key":"human-response-evidence","statement":"Response performance is based on actual human action, not automated acknowledgement."}],"openIssues":[],"summaryUseCases":null}', 're-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:consultation', 'Approved', '0.1.0');
VALUES('re-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:demanddiscovery-episode-spec', 1, 'maro', 1790142153080, 'maro2', 1790131488990, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"oneLineDefinition":"Turn traceable demand evidence into human-reviewed content and operational decisions.","businessPurpose":"Turn traceable demand evidence into human-reviewed content and operational decisions without inventing demand or automatically changing operations.","responsibleOrganization":null,"situationContext":{"startBusinessEvent":"Public, owned-channel, or de-identified consultation evidence becomes available.","businessSubject":"Recruitment demand evidence","endConditions":["Evidence-backed proposals are accepted, deferred, or rejected by a human without automatic operational change."]},"stakeholders":[{"key":"marketing-manager","name":"marketing-manager","role":"Marketing Manager","goals":["Prepare, review, and improve recruitment plans from demand evidence."],"protectedInterests":[]}],"acts":[{"key":"marketing-manager","name":"marketing-manager","stakeholderKey":"marketing-manager","responsibility":"Prepare and review evidence-backed recruitment plans."}],"useCases":[{"key":"evidence-based-demand-planning","name":"Evidence-based demand planning","actKey":"marketing-manager","userGoal":"Prepare a traceable content brief from demand evidence and available offers.","trigger":"Relevant public or de-identified evidence is available.","endConditions":["A traceable brief is linked to available offers or explicit unmet demand."],"capabilityNeeds":[{"key":"demand-planning-brief","providerMicroserviceCode":"growin","requiredCapabilityKey":"prepare-demand-brief","businessPurpose":"Convert evidence into a traceable brief.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"demand-analysis-review","name":"Demand analysis review","actKey":"marketing-manager","userGoal":"Decide whether to accept, defer, or reject an AI demand analysis.",