ved', '0.1.0');
VALUES('re-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:learning-episode-spec', 1, 'maro', 1790142158412, 'maro2', 1790131488994, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"oneLineDefinition":"Support voluntary learning and participant-controlled preferences, contact, consent, and data rights.","businessPurpose":"Support voluntary learning, explicit preferences, verified contact, and purpose-specific consent without creating unsolicited consultation transfers.","responsibleOrganization":null,"situationContext":{"startBusinessEvent":"A visitor arrives through content or a participation page.","businessSubject":"Learning participation and privacy choices","endConditions":["Learning progress and explicit choices are preserved without creating an unsolicited academy transfer."]},"stakeholders":[{"key":"contents-manager","name":"contents-manager","role":"Contents Manager","goals":["Prepare versioned learning and participation content."],"protectedInterests":[]},{"key":"marketing-manager","name":"marketing-manager","role":"Marketing Manager","goals":["Publish an approved participation experience."],"protectedInterests":[]},{"key":"rookie","name":"rookie","role":"Rookie","goals":["Learn voluntarily and control preferences, contact, consent, and data rights."],"protectedInterests":["Anonymous learning remains available without forced contact or marketing consent."]}],"acts":[{"key":"contents-manager","name":"contents-manager","stakeholderKey":"contents-manager","responsibility":"Prepare versioned engagement content."},{"key":"marketing-manager","name":"marketing-manager","stakeholderKey":"marketing-manager","responsibility":"Publish the approved participation experience."},{"key":"rookie","name":"rookie","stakeholderKey":"rookie","responsibility":"Learn voluntarily and control personal choices."}],"useCases":[{"key":"engagement-content-preparation","name":"Engagement content preparation","actKey":"contents-manager","userGoal":"Prepare reviewed, ve