VALUES('re-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:performance-episode-spec', 1, 'maro', 1790142163628, 'maro2', 1790131488999, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"oneLineDefinition":"Reconcile canonical source outcomes and report reproducible recruitment performance and costs.","businessPurpose":"Reconcile source outcomes and report reproducible conversion, retention, attribution, cost, and baseline comparisons without false certainty.","responsibleOrganization":null,"situationContext":{"startBusinessEvent":"Source enrollment, payment, refund, or attendance evidence arrives, or a reporting period requires analysis.","businessSubject":"Recruitment outcomes and performance evidence","endConditions":["Source outcomes are linked or held unresolved, and reports expose definitions, maturity, completeness, and limitations."]},"stakeholders":[{"key":"marketing-manager","name":"marketing-manager","role":"Marketing Manager","goals":["Reconcile ambiguous outcomes and review recruitment performance and costs."],"protectedInterests":[]},{"key":"academy-manager","name":"academy-manager","role":"Academy Manager","goals":["Review the authorized academy''s recruitment outcomes."],"protectedInterests":["Only the authorized academy''s results are visible."]}],"acts":[{"key":"marketing-manager","name":"marketing-manager","stakeholderKey":"marketing-manager","responsibility":"Reconcile source evidence and review performance and costs."},{"key":"academy-manager","name":"academy-manager","stakeholderKey":"academy-manager","responsibility":"Review authorized academy performance."}],"useCases":[{"key":"source-outcome-reconciliation","name":"Source outcome reconciliation","actKey":"marketing-manager","userGoal":"Resolve or explicitly hold ambiguous source enrollment and financial outcomes.","trigger":"Canonical source evidence arrives or an unresolved record needs review.","endConditions":["Evidence is linked once or held unresolved without unsupported confirmation."],"capabilityNeeds":[{"key":"source-reconciliation-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"reconcile-source-outcome","businessPurpose":"Reconcile canonical source evidence.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"recruitment-performance-review","name":"Recruitment performance review","actKey":"marketing-manager","userGoal":"Evaluate conversion, retention, and attribution with reproducible definitions.","trigger":"A reporting cohort, cutoff, and source-completeness context are selected.","endConditions":["Reports show denominators, periods, maturity, unknowns, exclusions, and rule versions."],"capabilityNeeds":[{"key":"performance-review-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"review-recruitment-performance","businessPurpose":"Review reproducible recruitment performance.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"recruitment-cost-comparison","name":"Recruitment cost comparison","actKey":"marketing-manager","userGoal":"Compare verified costs and documented baselines.","trigger":"Verified costs and a documented comparison scope exist.","endConditions":["Costs and baselines are reproducible without double counting or unsupported causal claims."],"capabilityNeeds":[{"key":"cost-comparison-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"compare-recruitment-costs","businessPurpose":"Compare recruitment costs and baselines.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"academy-performance-review","name":"Academy performance review","actKey":"academy-manager","userGoal":"Inspect the academy''s conversion, retention, and baseline results under shared definitions.","trigger":"An authorized academy operator requests the report.","endConditions":["Only the academy''s permitted results and limitations are shown."],"capabilityNeeds":[{"key":"academy-performance-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"review-academy-performance","businessPurpose":"Review the authorized academy''s results.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]}],"useCaseFlows":[],"dramaParticipations":[{"key":"marketing-performance-participation","microserviceCode":"growin","stakeholderKey":"marketing-manager","dramaRoleKey":"marketing-operator","accessPurpose":"Reconcile source outcomes and review network performance and costs.","accessConditions":["Canonical source ownership and unresolved evidence must remain explicit."]},{"key":"academy-performance-participation","microserviceCode":"growin","stakeholderKey":"academy-manager","dramaRoleKey":"academy-operator","accessPurpose":"Review authorized academy performance.","accessConditions":["Only the authorized academy''s results may be viewed."]}],"contexts":[],"eventReactions":null,"policies":[{"key":"no-false-certainty","category":"Reporting","name":"No false certainty","statement":"Pending, unknown, excluded, and unresolved evidence remains distinct from confirmed negative outcomes."}],"acceptanceCriteria":[{"key":"ambiguous-source-held","statement":"Ambiguous source evidence remains unresolved and does not automatically confirm performance or charges."},{"key":"report-definitions-visible","statement":"Performance reports expose denominators, periods, rule versions, source freshness, and comparison limitations."}],"openIssues":[],"summaryUseCases":null}', 're-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:performance', 'Approved', '0.1.0');
VALUES('re-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:recruitmentpreparation-episode-spec', 1, 'maro', 1790142168351, 'maro2', 1790131488983, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"oneLineDefinition":"Prepare recruitment networks, participating academies, eligible offers, and valid trial capacity.","businessPurpose":"Ensure that only participating academies with current eligible offers and valid trial schedules can receive new demand.","responsibleOrganization":null,"situationContext":{"startBusinessEvent":"A recruitment network is established, or an academy joins or changes its recruitment supply.","businessSubject":"Recruitment readiness","endConditions":["Only participating academies with current eligible offers and valid trial schedules can receive new demand."]},"stakeholders":[{"key":"marketing-manager","name":"marketing-manager","role":"Marketing Manager","goals":["Establish the recruitment network and register participating academies."],"protectedInterests":[]},{"key":"academy-manager","name":"academy-manager","role":"Academy Manager","goals":["Keep academy participation, offers, and trial capacity current."],"protectedInterests":["Other academies'' data remains inaccessible."]}],"acts":[{"key":"marketing-manager","name":"marketing-manager","stakeholderKey":"marketing-manager","responsibility":"Establish the recruitment network and register participating academies."},{"key":"academy-manager","name":"academy-manager","stakeholderKey":"academy-manager","responsibility":"Keep the academy ready for recruitment."}],"useCases":[{"key":"network-setup","name":"Recruitment network setup","actKey":"marketing-manager","userGoal":"Prepare an isolated regional and language recruitment network.","trigger":"A network is being established or an academy requests participation.","endConditions":["The network boundary and participating academy terms are recorded."],"capabilityNeeds":[{"key":"network-setup-configure-network","providerMicroserviceCode":"growin","requiredCapabilityKey":"configure-recruitment-network","businessPurpose":"Establish the recruitment operating boundary.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"network-setup-register-academy","providerMicroserviceCode":"growin","requiredCapabilityKey":"register-participating-academy","businessPurpose":"Register participating academy terms and scope.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"academy-recruitment-readiness","name":"Academy recruitment readiness","actKey":"academy-manager","userGoal":"Maintain an academy as an eligible destination for current recruitment demand.","trigger":"An authorized academy joins or changes its participation, offer, or trial capacity.","endConditions":["Participation information is current.","Eligible offers and valid trial schedules are available."],"capabilityNeeds":[{"key":"readiness-manage-participation","providerMicroserviceCode":"growin","requiredCapabilityKey":"manage-academy-participation","businessPurpose":"Maintain academy participation information.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"readiness-manage-offer","providerMicroserviceCode":"growin","requiredCapabilityKey":"manage-recruitment-offer","businessPurpose":"Maintain eligible recruitment offers.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"readiness-manage-trial","providerMicroserviceCode":"growin","requiredCapabilityKey":"manage-trial-schedule","businessPurpose":"Maintain valid trial capacity.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]}],"useCaseFlows":[],"dramaParticipations":[{"key":"marketing-recruitment-participation","microserviceCode":"growin","stakeholderKey":"marketing-manager","dramaRoleKey":"marketing-operator","accessPurpose":"Configure recruitment networks and participating academies.","accessConditions":["Requires authorized recruitment-network scope."]},{"key":"academy-recruitment-participation","microserviceCode":"growin","stakeholderKey":"academy-manager","dramaRoleKey":"academy-operator","accessPurpose":"Maintain the academy''s participation, offers, and trials.","accessConditions":["Limited to the authorized academy."]}],"contexts":[],"eventReactions":null,"policies":[{"key":"eligible-supply-only","category":"Recruitment","name":"Eligible supply only","statement":"Inactive, expired, incomplete, or unavailable offers cannot receive new applications."}],"acceptanceCriteria":[{"key":"current-supply-only","statement":"Only participating academies with current eligible offers and valid trial schedules receive new demand."}],"openIssues":[],"summaryUseCases":null}', 're-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:recruitmentpreparation', 'Approved', '0.1.0');
VALUES('re-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:referrals-episode-spec', 1, 'maro', 1790142172234, 'maro2', 1790131489001, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"oneLineDefinition":"Operate activated P1 referral participation and evidence-backed reward review without identity exposure or duplication.","businessPurpose":"Operate privacy-limited referral participation and approve evidence-backed rewards without exposing learner identities or duplicating rewards.","responsibleOrganization":null,"situationContext":{"startBusinessEvent":"A P1 partner or student referral program is explicitly activated.","businessSubject":"Referral participation and rewards","endConditions":["Referral links, aggregate performance, and reward decisions remain private, traceable, and non-duplicated."]},"stakeholders":[{"key":"marketing-manager","name":"marketing-manager","role":"Marketing Manager","goals":["Configure referral participation and approve eligible rewards with separate authority."],"protectedInterests":["Reward approval requires separate settlement authority."]},{"key":"rookie","name":"rookie","role":"Rookie","goals":["Use a personal referral link and inspect only personal aggregate performance."],"protectedInterests":["Other participants'' identities and payout credentials remain inaccessible."]}],"acts":[{"key":"marketing-manager","name":"marketing-manager","stakeholderKey":"marketing-manager","responsibility":"Configure referral participation and make separately authorized reward decisions."},{"key":"rookie","name":"rookie","stakeholderKey":"rookie","responsibility":"Use an authorized personal referral link and view personal aggregates."}],"useCases":[{"key":"referral-program-management","name":"Referral program management","actKey":"marketing-manager","userGoal":"Configure versioned partner and student referral participation.","trigger":"P1 referral participation and policy responsibility are approved.","endConditions":["A versioned program defines scope, links, eligibility, reward type, and validity."],"capabilityNeeds":[{"key":"referral-program-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"configure-referral-program","businessPurpose":"Configure the approved P1 referral program.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"referral-reward-review","name":"Referral reward review","actKey":"marketing-manager","userGoal":"Approve and track one evidence-backed reward per program and enrollment.","trigger":"Verified enrollment, attribution, and net-payment evidence satisfies the active program.","endConditions":["At most one eligible reward is approved per program and enrollment."],"capabilityNeeds":[{"key":"referral-reward-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"approve-referral-reward","businessPurpose":"Approve an evidence-backed referral reward.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"personal-referral-participation","name":"Personal referral participation","actKey":"rookie","userGoal":"Use an authorized referral link and view personal performance without seeing other participants.","trigger":"The advocate agreement and referral program are active.","endConditions":["The advocate can use a personal link and view only personal aggregate results."],"capabilityNeeds":[{"key":"personal-link-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"use-referral-link","businessPurpose":"Use the advocate''s personal referral link.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"personal-referral-results","providerMicroserviceCode":"growin","requiredCapabilityKey":"view-referral-performance","businessPurpose":"View only the advocate''s aggregate referral performance.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]}],"useCaseFlows":[{"key":"program-to-reward","fromUseCaseKey":"referral-program-management","toUseCaseKey":"referral-reward-review","flowType":"NORMAL","condition":"The active program has a verified eligible enrollment and net-payment outcome."}],"dramaParticipations":[{"key":"marketing-referral-configuration","microserviceCode":"growin","stakeholderKey":"marketing-manager","dramaRoleKey":"marketing-operator","accessPurpose":"Configure the approved referral program.","accessConditions":["P1, participation terms, and policy responsibility must be approved."]},{"key":"marketing-referral-approval","microserviceCode":"growin","stakeholderKey":"marketing-manager","dramaRoleKey":"settlement-reviewer","accessPurpose":"Approve evidence-backed referral rewards.","accessConditions":["Separate settlement authority and approved commercial rules are required."]},{"key":"rookie-referral-participation","microserviceCode":"growin","stakeholderKey":"rookie","dramaRoleKey":"learning-participant","accessPurpose":"Use a personal referral link and view personal aggregates.","accessConditions":["An active advocate agreement is required.","Participant identities remain inaccessible."]}],"contexts":[],"eventReactions":null,"policies":[{"key":"one-reward-per-program-enrollment","category":"Referral","name":"One reward per program and enrollment","statement":"A program and enrollment can produce at most one approved reward."},{"key":"advocate-privacy","category":"Privacy","name":"Advocate privacy boundary","statement":"Advocates may access only their own links and aggregate results, never participant identities."}],"acceptanceCriteria":[{"key":"no-duplicate-referral-reward","statement":"Replay or multiple advocate claims do not create more than one reward for a program and enrollment."},{"key":"advocate-sees-aggregates-only","statement":"An advocate cannot access referred participant identities or payout credentials."}],"openIssues":[{"key":"referral-activation-policy","question":"Which participation terms, reward rules, authority assignments, and payout integration are approved before P1 referral activation?","decision":null,"resolved":false,"blocking":false}],"summaryUseCases":null}', 're-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:referrals', 'Approved', '0.1.0');
VALUES('re-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:settlement-episode-spec', 1, 'maro', 1790142178064, 'maro2', 1790131489000, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"oneLineDefinition":"Review costs, charges, settlements, disputes, receipts, refunds, and immutable adjustments.","businessPurpose":"Determine academy charges from approved policy and verified evidence while preserving immutable confirmed records and preventing duplicate charges.","responsibleOrganization":null,"situationContext":{"startBusinessEvent":"A settlement period ends or a charge, collection, dispute, refund, or adjustment requires review.","businessSubject":"Academy settlement evidence","endConditions":["Charges, settlements, receipts, disputes, and adjustments are traceable, policy-backed, immutable, and non-duplicated."]},"stakeholders":[{"key":"marketing-manager","name":"marketing-manager","role":"Marketing Manager","goals":["Exercise separately granted settlement authority for commercial decisions."],"protectedInterests":["General marketing access does not grant settlement authority."]},{"key":"academy-manager","name":"academy-manager","role":"Academy Manager","goals":["Review the academy''s settlement and raise evidence-backed disputes."],"protectedInterests":["Confirmed source lines remain immutable."]}],"acts":[{"key":"marketing-manager","name":"marketing-manager","stakeholderKey":"marketing-manager","responsibility":"Use separately granted authority to approve policy, evaluate charges, and confirm or adjust settlements."},{"key":"academy-manager","name":"academy-manager","stakeholderKey":"academy-manager","responsibility":"Review the academy''s settlement and raise disputes."}],"useCases":[{"key":"commercial-policy-approval","name":"Commercial policy approval","actKey":"marketing-manager","userGoal":"Approve the policy version required for financial calculations.","trigger":"Contract-approved commercial values are ready.","endConditions":["An immutable effective-dated policy is approved."],"capabilityNeeds":[{"key":"commercial-policy-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"approve-commercial-policy","businessPurpose":"Approve the commercial policy version.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"shared-cost-allocation","name":"Shared cost allocation","actKey":"marketing-manager","userGoal":"Allocate verified common costs reproducibly across participating academies.","trigger":"A verified shared cost requires allocation.","endConditions":["Academy allocations reconcile exactly to the source amount."],"capabilityNeeds":[{"key":"shared-cost-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"allocate-shared-cost","businessPurpose":"Allocate the verified shared cost.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"acquisition-charge-review","name":"Acquisition charge review","actKey":"marketing-manager","userGoal":"Determine whether a new-student acquisition charge is eligible.","trigger":"Enrollment, origin, new-student, and net-payment evidence are available.","endConditions":["The charge is eligible, ineligible, or review-pending without duplication."],"capabilityNeeds":[{"key":"acquisition-fee-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"evaluate-acquisition-fee","businessPurpose":"Evaluate acquisition charge eligibility.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"settlement-finalization","name":"Settlement finalization","actKey":"marketing-manager","userGoal":"Confirm an immutable settlement and later record actual collection.","trigger":"Settlement evidence is reviewed under an approved policy.","endConditions":["The settlement is immutable and collection evidence remains separate."],"capabilityNeeds":[{"key":"settlement-confirmation-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"confirm-settlement","businessPurpose":"Confirm the immutable settlement.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"settlement-receipt-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"record-settlement-receipt","businessPurpose":"Record actual collection separately.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"refund-adjustment","name":"Refund adjustment","actKey":"marketing-manager","userGoal":"Apply a refund without rewriting a confirmed charge.","trigger":"A verified refund affects an existing charge.","endConditions":["An unconfirmed charge is recalculated or one unique referenced adjustment is recorded."],"capabilityNeeds":[{"key":"refund-adjustment-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"adjust-charge-after-refund","businessPurpose":"Apply the refund under the approved policy.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]},{"key":"academy-settlement-review","name":"Academy settlement review","actKey":"academy-manager","userGoal":"Inspect charges and dispute unsupported items without altering confirmed lines.","trigger":"An authorized academy settlement is available for review.","endConditions":["The academy''s review or dispute evidence is recorded while the original remains unchanged."],"capabilityNeeds":[{"key":"academy-settlement-query","providerMicroserviceCode":"growin","requiredCapabilityKey":"review-academy-settlement","businessPurpose":"Inspect the academy settlement and evidence.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true},{"key":"academy-dispute-need","providerMicroserviceCode":"growin","requiredCapabilityKey":"raise-settlement-dispute","businessPurpose":"Record an evidence-backed dispute.","inputContextKeys":[],"expectedResultKeys":[],"mandatory":true}]}],"useCaseFlows":[{"key":"policy-to-allocation","fromUseCaseKey":"commercial-policy-approval","toUseCaseKey":"shared-cost-allocation","flowType":"NORMAL","condition":"A verified shared cost must be allocated under the approved policy."},{"key":"charge-to-finalization","fromUseCaseKey":"acquisition-charge-review","toUseCaseKey":"settlement-finalization","flowType":"NORMAL","condition":"Charge evidence has been reviewed for the settlement period."},{"key":"finalization-to-adjustment","fromUseCaseKey":"settlement-finalization","toUseCaseKey":"refund-adjustment","flowType":"ALTERNATIVE","condition":"A verified refund later affects a confirmed charge."}],"dramaParticipations":[{"key":"marketing-settlement-participation","microserviceCode":"growin","stakeholderKey":"marketing-manager","dramaRoleKey":"settlement-reviewer","accessPurpose":"Make separately authorized commercial and settlement decisions.","accessConditions":["Separate settlement authority and approved commercial values are required."]},{"key":"academy-settlement-participation","microserviceCode":"growin","stakeholderKey":"academy-manager","dramaRoleKey":"academy-operator","accessPurpose":"Review and dispute the authorized academy''s settlement.","accessConditions":["Limited to the authorized academy; confirmed source lines cannot be edited."]}],"contexts":[],"eventReactions":null,"policies":[{"key":"approved-values-only","category":"Finance","name":"Approved values only","statement":"No charge or reward may use an invented or unapproved commercial value."},{"key":"confirmed-record-immutability","category":"Finance","name":"Confirmed record immutability","statement":"Confirmed settlements and lines are preserved; later corrections use referenced adjustments."}],"acceptanceCriteria":[{"key":"allocation-reconciles","statement":"Allocated academy amounts equal the verified source cost after approved rounding treatment."},{"key":"refund-adjustment-unique","statement":"A verified refund creates at most one adjustment for the referenced confirmed line."}],"openIssues":[{"key":"settlement-commercial-values","question":"Which commercial rates, minimum-payment rules, hold periods, allocation rules, and refund treatments are approved for activation?","decision":null,"resolved":false,"blocking":false}],"summaryUseCases":null}', 're-target-system:growin-architecture:1.0-bc:growin-application:growin-micro-app:settlement', 'Approved', '0.1.0');

VALUES('re-target-system:growin-architecture:1.0-bc:growin-ms:growin', 0, 'maro2', 1790131488952, 'maro2', 1790131488952, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', 'growin', 'Own the recruitment-growth journey and its commercial evidence: recruitment networks and offers, demand evidence, reviewed content and campaigns, voluntary learning participation, preferences and consent, academy selection and consultation transfer, trial booking, outcome projections, attribution, costs, settlements, and referral rewards.', 'LoB', 'Growin', 'Business', 're-target-system:growin-architecture:1.0-bc:growin', NULL);
VALUES('re-target-system:growin-architecture:1.0-bc:growin-ms:growin-drama-spec', 1, 'maro', 1790142198158, 'maro2', 1790131488959, 'mb@NT:1:1-6', 'NT:1', 'NT:1:1-6', '{"businessPurpose":"Own the cohesive recruitment-growth business journey and preserve its operational and commercial evidence while canonical source systems retain their ledgers.","ownerOrganization":null,"responsibilityBoundary":{"coreResponsibilities":["Own recruitment networks, participating academy profiles, eligible offers, and trial schedules.","Own demand evidence, reviewed content revisions, campaigns, publications, and acquisition links.","Own voluntary learning participation, preferences, purpose-specific consent, recommendations, transfers, bookings, and waitlists.","Own source projections, attribution decisions, performance evidence, costs, settlements, and referral reward decisions."],"nonResponsibilities":["Do not own canonical student, enrollment, course, attendance, Lead, consultation, payment, or refund ledgers.","Do not execute tax invoices, remittances, or reward payouts.","Do not own identity, authorization, secret storage, file storage, content generation, or notification delivery.","Do not provide a free-form page builder or P0 automatic pronunciation assessment."]},"stakeholders":[{"key":"marketing-operator","name":"Marketing Operator","role":"Operate recruitment networks, demand evidence, campaigns, waitlists, consultation support, outcome reconciliation, reporting, and authorized commercial work.","goals":["Operate the recruitment journey using traceable evidence and approved authority."],"protectedInterests":["Financial authority must be granted separately from general marketing access."]},{"key":"content-producer","name":"Content Producer","role":"Plan, produce, localize, and prepare versioned recruitment and learning content.","goals":["Prepare rights-supported content for qualified review."],"protectedInterests":["Unmasked consultation contacts remain inaccessible."]},{"key":"content-reviewer","name":"Content Reviewer","role":"Record independently qualified Korean-learning or local-language decisions on fixed revisions.","goals":["Ensure publication uses a revision with both required qualified reviews."],"protectedInterests":["Review decisions remain revision-specific and independently qualified."]},{"key":"academy-operator","name":"Academy Operator","role":"Manage academy recruitment, trial capacity, consultation work, performance, and settlement review within an authorized academy boundary.","goals":["Operate academy-owned work without crossing academy boundaries."],"protectedInterests":["Other academies'' data and unauthorized commercial approval remain inaccessible."]},{"key":"learning-participant","name":"Learning Participant","role":"Learn voluntarily, manage preferences and consent, choose an academy, and request consultation or trials.","goals":["Control personal participation and explicitly selected academy connections."],"protectedInterests":["No unsolicited transfer, identity exposure, or forced marketing consent."]},{"key":"settlement-reviewer","name":"Settlement Reviewer","role":"Exercise separately granted authority for commercial policy, charge eligibility, settlement confirmation, and reward approval.","goals":["Make immutable, evidence-backed commercial decisions."],"protectedInterests":["Unapproved values and duplicate charges must never be used."]}],"businessConcepts":[{"key":"recruitment-network","name":"Recruitment Network","definition":"The Growin-owned regional, language, locale, time-zone, currency, and operating boundary for recruitment.","identityCriteria":"A distinct Growin recruitment network within the selected bounded context.","ownershipType":"OWNED"},{"key":"academy-participation","name":"Academy Participation","definition":"The Growin-owned participation agreement and authorized operating boundary for an academy.","identityCriteria":"An academy''s participation in a recruitment network for an effective period.","ownershipType":"OWNED"},{"key":"recruitment-offer","name":"Recruitment Offer","definition":"A Growin-owned public recruitment offer that references a source course and is evaluated for current eligibility.","identityCriteria":"An academy offer linked to a source course within Growin.","ownershipType":"OWNED"},{"key":"trial-schedule","name":"Trial Schedule","definition":"Growin-owned trial capacity and booking availability, distinct from paid-course capacity.","identityCriteria":"A trial opportunity associated with a recruitment offer.","ownershipType":"OWNED"},{"key":"demand-evidence","name":"Demand Evidence","definition":"Traceable public, owned-channel, or de-identified evidence used for human-reviewed recruitment planning.","identityCriteria":"A sourced demand observation for a region and period.","ownershipType":"OWNED"},{"key":"content-revision","name":"Content Revision","definition":"A fixed, versioned recruitment or learning content revision with assets, rights evidence, next action, and review decisions.","identityCriteria":"A revision of a content item for a locale and format.","ownershipType":"OWNED"},{"key":"campaign","name":"Campaign","definition":"A shared-network or academy-owned recruitment campaign whose origin, participants, period, budget, and actual evidence are preserved.","identityCriteria":"A Growin campaign with fixed origin ownership.","ownershipType":"OWNED"},{"key":"participant","name":"Participant","definition":"An anonymous or contact-verified learner identity managed without merging people merely because they share contact details.","identityCriteria":"An opaque participant identity within a recruitment network.","ownershipType":"OWNED"},{"key":"purpose-consent","name":"Purpose Consent","definition":"Append-only evidence of a participant''s grant or withdrawal by purpose, channel, and recipient academy.","identityCriteria":"The latest decision for a participant, purpose, channel, and recipient academy.","ownershipType":"OWNED"},{"key":"academy-transfer","name":"Academy Transfer","definition":"Growin''s idempotent record and durable intent to transfer a consenting participant to an explicitly selected academy.","identityCriteria":"A participant''s active transfer request for an academy and offer scope.","ownershipType":"OWNED"},{"key":"trial-booking","name":"Trial Booking","definition":"Growin''s capacity-protected trial reservation and its change, cancellation, and attendance evidence.","identityCriteria":"A participant''s effective booking for a trial schedule.","ownershipType":"OWNED"},{"key":"source-outcome","name":"Source Outcome","definition":"A Growin projection of canonical enrollment, payment, refund, or attendance evidence.","identityCriteria":"The canonical source identifier supplied by the owning external system.","ownershipType":"SNAPSHOT"},{"key":"commercial-policy","name":"Commercial Policy","definition":"An approved, effective-dated and immutable policy version used for commercial decisions.","identityCriteria":"A named policy version with an effective period.","ownershipType":"OWNED"},{"key":"settlement","name":"Settlement","definition":"A Growin-owned academy settlement whose confirmed evidence and source lines remain immutable.","identityCriteria":"An academy, settlement period, currency, and revision.","ownershipType":"OWNED"},{"key":"referral-program","name":"Referral Program","definition":"A versioned P1 program governing privacy-limited referral participation and reward eligibility.","identityCriteria":"A referral program version and validity period.","ownershipType":"OWNED"}],"capabilities":[{"key":"configure-recruitment-network","name":"Configure Recruitment Network","capabilityType":"COMMAND","businessGoal":"Establish a region, language, locale, time-zone, currency, and operating boundary for recruitment.","stakeholderKeys":["marketing-operator"],"trigger":"An authorized operator establishes or changes a recruitment network.","preconditions":["The operator has network-configuration authority."],"businessResults":["A usable recruitment network boundary is recorded."],"domainEventKeys":[],"businessConceptKeys":["recruitment-network"]},{"key":"register-participating-academy","name":"Register Participating Academy","capabilityType":"COMMAND","businessGoal":"Record an academy''s participation terms, operating calendar, responsible users, and policy references.","stakeholderKeys":["marketing-operator"],"trigger":"An academy requests participation and its source reference is confirmed.","preconditions":["The academy source reference is confirmed."],"businessResults":["Academy participation terms and operating scope are recorded."],"domainEventKeys":[],"businessConceptKeys":["academy-participation"]},{"key":"manage-academy-participation","name":"Manage Academy Participation","capabilityType":"COMMAND","businessGoal":"Keep an authorized academy''s public recruitment profile and participation information current.","stakeholderKeys":["academy-operator"],"trigger":"An authorized academy changes its participation information.","preconditions":["The operator is authorized for the academy."],"businessResults":["Current academy participation information is available within the academy boundary."],"domainEventKeys":[],"businessConceptKeys":["academy-participation"]},{"key":"manage-recruitment-offer","name":"Manage Recruitment Offer","capabilityType":"COMMAND","businessGoal":"Publish and refresh only complete, current, available recruitment offers.","stakeholderKeys":["academy-operator"],"trigger":"An academy creates or refreshes a recruitment offer.","preconditions":["The academy participation is valid."],"businessResults":["Only eligible offers are available for new recruitment demand."],"domainEventKeys":[],"businessConceptKeys":["academy-participation","recruitment-offer"]},{"key":"manage-trial-schedule","name":"Manage Trial Schedule","capabilityType":"COMMAND","businessGoal":"Maintain trial times, locations, capacity, and booking deadlines independently from paid-course capacity.","stakeholderKeys":["academy-operator"],"trigger":"An academy prepares or changes trial availability.","preconditions":["The related recruitment offer supports a trial."],"businessResults":["Current trial availability is recorded without rewriting existing bookings."],"domainEventKeys":[],"businessConceptKeys":["recruitment-offer","trial-schedule"]},{"key":"prepare-demand-brief","name":"Prepare Demand Brief","capabilityType":"COMMAND","businessGoal":"Convert traceable public or de-identified evidence into a content brief linked to available offers or unmet demand.","stakeholderKeys":["marketing-operator"],"trigger":"Relevant demand evidence becomes available.","preconditions":["Evidence has a traceable source, region, and period."],"businessResults":["An evidence-backed brief or explicit unmet demand is recorded."],"domainEventKeys":[],"businessConceptKeys":["demand-evidence","recruitment-offer"]},{"key":"review-demand-analysis","name":"Review Demand Analysis","capabilityType":"COMMAND","businessGoal":"Accept, defer, or reject evidence-backed AI findings without automatically changing operations.","stakeholderKeys":["marketing-operator"],"trigger":"A P1 demand analysis is ready for human review.","preconditions":["The analysis includes evidence, uncertainty, model version, and sample context."],"businessResults":["A human review decision and evidence are preserved."],"domainEventKeys":[],"businessConceptKeys":["demand-evidence"]},{"key":"evaluate-operational-improvement","name":"Evaluate Operational Improvement","capabilityType":"COMMAND","businessGoal":"Assess P2 proposals with sample size, observation period, and human decision evidence.","stakeholderKeys":["marketing-operator"],"trigger":"A P2 improvement proposal is ready for review.","preconditions":["The proposal includes sufficient review context."],"businessResults":["A human decision is recorded without automatic operational change."],"domainEventKeys":[],"busin