ipants, period, audience, budget, and origin.","stakeholderKeys":["marketing-operator"],"trigger":"Recruitment content and campaign intent are available.","preconditions":["Campaign ownership and participating academies are identifiable."],"businessResults":["Campaign origin and budget remain distinct from actual expenditure."],"domainEventKeys":[],"businessConceptKeys":["campaign"]},{"key":"publish-approved-content","name":"Publish Approved Content","capabilityType":"COMMAND","businessGoal":"Schedule and record the actual publication result of a fully reviewed revision.","stakeholderKeys":["marketing-operator"],"trigger":"An approved revision and usable channel are ready.","preconditions":["Both required reviews apply to the same fixed revision.","Rights evidence and a valid next action are present."],"businessResults":["Actual publication success or failure is recorded distinctly from scheduling."],"domainEventKeys":[],"businessConceptKeys":["content-revision","campaign"]},{"key":"issue-tracking-link","name":"Issue Tracking Link","capabilityType":"COMMAND","businessGoal":"Create a privacy-safe link preserving campaign, channel, academy, or referral ownership.","stakeholderKeys":["marketing-operator"],"trigger":"A campaign, publication, or approved referral path needs a public link.","preconditions":["The destination and ownership context are valid."],"businessResults":["A server-validated link is issued without personal data in its URL."],"domainEventKeys":[],"businessConceptKeys":["campaign"]},{"key":"record-channel-performance","name":"Record Channel Performance","capabilityType":"COMMAND","businessGoal":"Record sourced channel aggregates and actual advertising expenditure without confusing views with consultation candidates.","stakeholderKeys":["marketing-operator"],"trigger":"Channel reporting or expenditure evidence is available.","preconditions":["The source and reporting period are known."],"businessResults":["Channel aggregates and actual spend are recorde