ts an action requiring verified contact.","preconditions":["An approved verification provider and path are available."],"businessResults":["The selected contact is verified for the correct participant identity."],"domainEventKeys":[],"businessConceptKeys":["participant"]},{"key":"recover-participant-access","name":"Recover Participant Access","capabilityType":"COMMAND","businessGoal":"Restore access to the correct participant identity through an approved verification path.","stakeholderKeys":["learning-participant"],"trigger":"A participant requests access recovery.","preconditions":["An approved recovery verification path is available."],"businessResults":["Access is restored without merging distinct participants."],"domainEventKeys":[],"businessConceptKeys":["participant"]},{"key":"manage-purpose-consent","name":"Manage Purpose Consent","capabilityType":"COMMAND","businessGoal":"Grant or withdraw consent independently by purpose, channel, and recipient academy.","stakeholderKeys":["learning-participant"],"trigger":"A participant reviews or changes a consent choice.","preconditions":["The applicable notice and recipient are presented."],"businessResults":["An append-only purpose-specific consent decision is recorded."],"domainEventKeys":[],"businessConceptKeys":["participant","purpose-consent"]},{"key":"request-personal-data-change","name":"Request Personal Data Change","capabilityType":"COMMAND","businessGoal":"Request correction, withdrawal, deletion, or retention-expiry processing with a traceable result.","stakeholderKeys":["learning-participant"],"trigger":"A verified participant submits a data-rights request.","preconditions":["The participant''s authority over the affected data is verified."],"businessResults":["The request and its outcome are traceable subject to approved retention obligations."],"domainEventKeys":[],"businessConceptKeys":["participant"]},{"key":"compare-recruitment-offers","name":"Compare Recruitment Offers","capabilityType":"QUERY","busin