"businessRules":[{"key":"ownership-boundary","category":"Ownership","name":"Source ownership boundary","statement":"Growin owns recruitment-growth records and projections but does not replace canonical Lead, consultation, enrollment, attendance, payment, or refund ledgers."},{"key":"participant-transfer-separation","category":"Consent","name":"Learning and transfer separation","statement":"Anonymous learning, preference, consent, academy transfer, consultation, booking, enrollment, and payment remain distinct business facts."},{"key":"recipient-specific-consent","category":"Consent","name":"Recipient-specific transfer consent","statement":"Academy transfer requires explicit academy choice, verified contact, and current consent for that recipient academy."},{"key":"content-dual-review","category":"Content","name":"Dual fixed-revision review","statement":"Publication requires Korean-learning and local-language approvals on the same fixed revision; later changes require a new reviewed revision."},{"key":"capacity-protection","category":"Booking","name":"Trial capacity protection","statement":"Trial holds and confirmed bookings never exceed trial capacity; failed changes preserve the original booking and cancellation releases a seat exactly once."},{"key":"human-response-semantics","category":"Consultation","name":"Human response semantics","statement":"A human contact attempt may satisfy response timing, but successful contact is a distinct fact and automated acknowledgement satisfies neither."},{"key":"source-idempotency","category":"Integration","name":"Source-effect idempotency","statement":"Each source event or financial transaction has business effect at most once, and stale state updates do not overwrite newer evidence."},{"key":"immutable-commercial-evidence","category":"Finance","name":"Immutable commercial evidence","statement":"Approved policies and confirmed settlements are not rewritten; refunds create recalculation before confirmation or unique referenced 