EventKeys":[],"failureHandling":"Hold ambiguous or incomplete outcomes without confirming unsupported performance or charges."},{"targetMicroserviceCode":null,"externalParty":"Payment and payout systems","purpose":"Receive canonical payment and refund facts and delegate collection, remittance, and reward payout execution.","requiredCapabilities":["Payment and refund evidence","Collection evidence","Reward payout result"],"inputFacts":["Canonical payment, refund, collection, and payout results"],"requestedActions":["Collect or remit an externally approved obligation","Execute an approved reward payout"],"expectedResults":["Source-linked evidence remains separate from Growin settlement or reward approval"],"consumedDomainEventKeys":[],"providedDomainEventKeys":[],"failureHandling":"Do not rewrite confirmed Growin evidence; preserve unresolved external execution separately."},{"targetMicroserviceCode":null,"externalParty":"Identity, file, generation, messaging, and channel platforms","purpose":"Reuse platform capabilities for verification, protected assets, generation, delivery, and publication.","requiredCapabilities":["Contact verification and access recovery","Protected file references","Asynchronous generation","Purpose-aware message delivery","Authorized channel publication"],"inputFacts":["Verified contact outcomes","Generation, file, delivery, and publication results"],"requestedActions":["Verify or recover participant access","Generate or store protected content","Deliver an authorized message","Publish approved content"],"expectedResults":["Provider outcomes remain traceable and do not bypass Growin consent or content review"],"consumedDomainEventKeys":[],"providedDomainEventKeys":[],"failureHandling":"Preserve the business request independently from provider delivery, expose failure, and use approved retry and reconciliation policies."}],"minimumGuarantees":["A failed external transfer or provider call does not erase an accepted local business request.","Unresolved source evidence is held explicitly rather than converted into unsupported enrollment, payment, charge, or reward facts.","Consent withdrawal blocks new applicable transfers and messages after the latest consent check.","Confirmed bookings, policies, settlements, and source financial facts are not silently overwritten."],"successGuarantees":["Eligible recruitment supply is current and academy-scoped.","Published content references the fixed revision that received both required reviews.","Consultation transfer and trial booking reflect explicit academy choice, verified contact, consent, and capacity.","Performance and settlement results retain source evidence, policy versions, denominators, and deduplication meaning."],"qualityRequirements":[{"key":"service-tenant-isolation","category":"Security","expectation":"Every network, academy, participant, export, and background operation enforces server-side scope.","measure":"T04 passes and no protected cross-boundary result is returned."},{"key":"service-idempotency","category":"Reliability","expectation":"Transfers, source facts, financial transactions, charges, and adjustments have at-most-once business effect.","measure":"T10 and T12-T18 pass under replay and out-of-order delivery."},{"key":"service-booking-integrity","category":"Concurrency","expectation":"Capacity and booking changes remain consistent under concurrent requests and failure.","measure":"T07-T08 pass with zero overbooking."},{"key":"service-auditability","category":"Audit","expectation":"Consent, transfer, review, commercial, and settlement decisions retain actor, evidence, and applicable version references.","measure":"A reviewer can reconstruct each protected decision without exposing raw secrets in audit output."}],"acceptanceCriteria":[{"key":"anonymous-learning-does-not-transfer","statement":"Completing anonymous practice creates no academy Lead or transfer intent."},{"key":"dual-review-blocks-publication","statement":"Publication is blocked u